"""Fight training (Train → Fight): the coach that calls combos over timed rounds, the combo library, drills, six fight
programs in Routines, saving a session to History, filling a program workout's rounds, and the backup."""
import asyncio, json, re, subprocess, sys, time
from playwright.async_api import async_playwright
PORT = 8776
srv = subprocess.Popen([sys.executable, '-m', 'http.server', str(PORT), '-d', 'dist'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
URL = f'http://localhost:{PORT}/'; results = []
def check(name, ok, detail=''):
    results.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + name + (' - ' + str(detail) if detail else ''))
# A stand-in voice that records what the coach says
SPEECH = """try { localStorage.setItem('liftbook.tourDone', '1') } catch (e) {}
window.__said = []; window.SpeechSynthesisUtterance = function (t) { this.text = t; };
Object.defineProperty(window, 'speechSynthesis', { value: { speak: u => window.__said.push(u.text), cancel: () => {} }, configurable: true });"""
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await (await b.new_context(viewport={'width': 390, 'height': 844})).new_page(); errs = []
        await pg.add_init_script(SPEECH); pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(URL); await pg.wait_for_timeout(1500); ev = pg.evaluate
        # Data
        bad = await ev("Object.entries(FCOMBOS).flatMap(([s, l]) => l.filter(([c]) => fToks(c).some(t => !FMOVES[t])).map(([c]) => s + ':' + c))")
        check('every combo uses known moves', not bad, bad[:5])
        cnt = await ev("Object.fromEntries(Object.entries(FCOMBOS).map(([s, l]) => [s, [1, 2, 3].map(n => l.filter(x => x[1] === n).length)]))")
        check('four styles, each with combos at all three levels', len(cnt) == 4 and all(min(v) >= 6 for v in cnt.values()), cnt)
        check('Muay Thai has knees and elbows; boxing has none', await ev("FCOMBOS.thai.some(([c]) => /knee|elb/.test(c)) && !FCOMBOS.box.some(([c]) => /knee|elb|teep|lk|bk|hk|swk|level|double|sprawl/.test(c))"))
        check('MMA has level changes and sprawls', await ev("FCOMBOS.mma.some(([c]) => /level|double|single/.test(c)) && FCOMBOS.mma.some(([c]) => /sprawl/.test(c))"))
        check('spoken as numbers or names', await ev("fSpeak('1-2-3b-slip', true) === 'one, two, three body, Slip' && fSpeak('1-2', false) === 'Jab, Cross'"))
        pools = await ev("({ b1: fightPool({ ...FDEF, level: 1 }).map(x => x.c), def: fightPool({ ...FDEF, level: 2, focus: 'def' }).map(x => x.c), off: fightPool({ ...FDEF, level: 3, focus: 'off' }).map(x => x.c) })")
        lv = dict((c, l) for c, l in await ev('FCOMBOS.box'))
        check('beginner pool only has beginner combos', all(lv[c] == 1 for c in pools['b1']))
        check('defense focus calls defense; offense has none', all(re.search(r'slip|roll|pull|block|parry|duck|check', c) for c in pools['def']) and not any(re.search(r'slip|roll|pull|block|parry|duck|pivot|step|in|out', c) for c in pools['off']))
        check('starred combos come up more often', await ev("fightPool({ ...FDEF, fav: ['box:1-2'] }).find(x => x.c === '1-2').w === 6"))
        check('at least 30 drills, all with steps', await ev("FDRILLS.length >= 30 && FDRILLS.every(d => d[4].length >= 2 && d[5])"))
        progs = await ev("BUILTIN_ROUTINES.filter(r => r.info && r.info.fight).map(r => ({ id: r.id, days: r.days.length, tags: r.days.map(d => d.tags[0]), unknown: r.days.some(d => d.items.some(i => getEx(i.ex).name === 'Unknown exercise')), fill: r.days.filter(d => d.fight).every(d => d.fight.fill && d.items.some(i => i.ex === d.fight.fill)) }))")
        check('six fight programs, tagged Fight training', len(progs) == 6 and all(t == 'Fight training' for p in progs for t in p['tags']), [p['id'] for p in progs])
        check('no unknown exercises; coach days fill an exercise in the day', all(not p['unknown'] and p['fill'] for p in progs))
        check('round exercises log time', await ev("['Shadowboxing Rounds', 'Heavy Bag Rounds', 'Jump Rope', 'BJJ Solo Movement Rounds'].every(n => exKind(findIn(BUILTIN_EX)(n).id) === 'timed')"))
        text = await ev("JSON.stringify([FPROGS, FDRILLS, FIGHT_NOTE])")
        brands = [w for w in ['UFC', 'Gracie', 'Everlast', 'Title Boxing', 'Hevy', 'Boostcamp', 'Tyson', 'Mayweather', 'CrossFit'] if w.lower() in text.lower()]
        check('generic names only', not brands, brands)
        check('coach note: not a substitute for a coach, supervised sparring', 'not a substitute for a qualified coach' in text and 'supervision' in text)
        # Screen
        await pg.locator('.topsw button', has_text='Fight').click(); await pg.wait_for_timeout(300)
        check('Train has a Fight switch with four tabs', await pg.locator('.fight-seg button').count() == 4 and await pg.locator('.topsw.four').count() == 1)
        await pg.click('#fc-rounds-up'); await pg.wait_for_timeout(500)
        check('settings are saved', await ev("S.meta.fight.rounds === 4") and (await pg.locator('#fc-total').inner_text()) == '11:10')
        await pg.click('#fc-rounds-dn'); await pg.wait_for_timeout(300)
        short = await ev("[].concat(...Object.keys(FCOMBOS).map(st => [1, 2, 3].flatMap(l => ['off', 'def', 'foot'].filter(f => fFocusShort({ style: st, level: l, focus: f })).map(f => st + l + f))))")
        check('every focus has at least 4 combos at every style and level', not short, short)
        await pg.locator('.fc-preset', has_text='Pro rounds').click(); await pg.wait_for_timeout(300)
        check('a quick start runs without changing your settings', await ev("FR.T.cfg.rounds === 6 && S.meta.fight.rounds === 3 && S.meta.fight.level === 1"))
        await ev("UI.setTab('routines')"); await pg.wait_for_timeout(400)
        check('while rounds run, a bar shows on other screens', await pg.locator('#fight-mini').count() == 1)
        await pg.click('#fight-mini .mini-open'); await pg.wait_for_timeout(300)
        check('the bar opens the coach', await pg.locator('#fight-run').count() == 1)
        await ev("UI.setView(null)"); await pg.wait_for_timeout(300)
        check('Coach shows the rounds in progress instead of a new Start', await pg.locator('#fight-now').count() == 1 and await pg.locator('#fight-start').count() == 0)
        await ev("fightGo({ ...fightSt(), rounds: 2 })"); await pg.wait_for_timeout(200)
        check('starting again opens the running rounds, never replaces them', await ev("FR.T.cfg.rounds === 6"))
        await ev("fightStop(); UI.setView(null)"); await pg.wait_for_timeout(300)
        await ev("startInterval({ id: 'x', mode: 'intervals', prep: 0, work: 20, rest: 10, rounds: 2, sets: 1 }); fightGo(fightSt())"); await pg.wait_for_timeout(200)
        check('the coach won’t start over a running interval timer', await ev("!FR.T"))
        await ev("S.itimer = null; UI.setView(null)"); await pg.wait_for_timeout(300)
        check('Your rounds card summarizes the settings', 'Boxing · beginner' in await pg.locator('#fc-summary').inner_text())
        # Coach run, with the clock moved forward
        await pg.click('#fight-start'); await pg.wait_for_timeout(300)
        check('starting opens the coach and says get ready', await pg.locator('#fight-run').count() == 1 and 'Get ready' in (await ev('__said'))[0])
        await ev("FR.T.startedAt -= 10500"); await pg.wait_for_timeout(2500)
        said = await ev('__said'); call = await pg.locator('#fight-call').inner_text()
        check('round 1 starts with the bell and a callout', 'Round 1' in said and len(said) >= 3, said[:5])
        check('the combo shows on screen as numbers and names', re.search(r'\d', call) and re.search(r'Jab|Cross|hook|uppercut|Slip|Pull|Block|Step|Roll|Parry|Duck', call), call)
        await ev("FR.T.startedAt -= (120 - 1.5 - 12) * 1000"); await pg.wait_for_timeout(800)
        check('burnout in the last 10 s of a round', 'Burnout' in (await ev('__said'))[-1] and 'BURNOUT' in (await pg.locator('#fight-call').inner_text()).upper())
        await ev("FR.T.startedAt -= 12000"); await pg.wait_for_timeout(600)
        said2 = await ev('__said')
        check('rest after the round, with rounds to go', await ev("FR.T.roundsDone") == 1 and any('Rest' in x and '2 to go' in x for x in said2))
        await pg.click('#fight-pause'); await pg.wait_for_timeout(200); n0 = len(await ev('__said'))
        await ev("FR.T.pausedAt -= 30000"); await pg.wait_for_timeout(600)
        check('pause stops the clock and the calls', await ev("FR.T.pausedAt > 0") and len(await ev('__said')) == n0)
        await pg.click('#fight-voice'); await pg.wait_for_timeout(500)
        check('voice switch on the coach is remembered', await ev("S.meta.fight.voice === false && FR.T.cfg.voice === false"))
        await pg.click('#fight-voice'); await pg.wait_for_timeout(300)
        await pg.click('#fight-pause'); await ev("FR.T.startedAt -= 999000"); await pg.wait_for_timeout(600)
        check('finishes after the last round', await pg.locator('#fight-done').count() == 1 and await ev("FR.T.done && FR.T.roundsDone === 3"))
        await pg.click('#fight-save'); await pg.wait_for_timeout(500)
        s = await ev("sessionList().find(s => s.fight)")
        check('saved to History as a boxing activity with rounds', s and s['activity'] == 'boxing' and s['fight']['rounds'] == 3 and s['name'] == 'Shadowboxing · Boxing', s and s['name'])
        check('counts toward the week like any workout', await ev("sessionList().filter(s => s.kind === 'activity').length") == 1)
        await pg.click('#fight-close'); await pg.wait_for_timeout(300)
        check('summary shows last 7 days', '3 rounds' in await pg.locator('#fight-week').inner_text())
        # Ended early: partial rounds
        await ev("fightStart({ ...fightSt(), style: 'thai', rounds: 5, round: 180, rest: 120 }); FR.T.startedAt -= (10 + 180 + 5) * 1000"); await pg.wait_for_timeout(500)
        await ev("UI.setView({ type: 'fight' })"); await pg.wait_for_timeout(200); await pg.click('#fight-end'); await pg.wait_for_timeout(200)
        check('ending early keeps the rounds done', '1' == (await pg.locator('#fight-done .tm-big').inner_text()).strip())
        await pg.click('#fight-close')
        # BJJ solo calls movements
        await ev("__said.length = 0; fightStart({ ...FDEF, style: 'bjj', rounds: 2, round: 60, rest: 30 }); FR.T.startedAt -= 10500"); await pg.wait_for_timeout(2600)
        said = ' '.join(await ev('__said'))
        check('BJJ solo calls movements, not punches', any(x in said for x in ['Shrimp', 'Bridge', 'stand-up', 'Sit-out', 'crawl', 'Sprawl', 'Hip', 'Crab', 'Leg circles']) and await ev("FR.T.call && !!FR.T.call.bjj"), [said, await ev('JSON.stringify(FR.T && FR.T.call)')])
        await ev("fightStop()")
        check('beginner BJJ never calls rolls or breakfalls', await ev("(() => { const seen = new Set(); for (let i = 0; i < 300; i++) { const T = { cfg: { ...FDEF, style: 'bjj', level: 1 }, call: null, calls: 0 }; fightCall(T, 0); seen.add(T.call.c); } return [...seen].every(c => !/roll$|Breakfall/.test(c) || c === 'Bridge and roll'); })()"))
        # Drill one combo
        await ev("UI.setView(null)"); await pg.wait_for_timeout(200)
        await pg.click('#fight-tab-combos'); await pg.wait_for_timeout(200)
        check('combo library lists combos and the move key', await pg.locator('.fc-row').count() >= 30 and await pg.locator('#fc-key').count() == 1)
        await pg.locator('.fc-star').first.click(); await pg.wait_for_timeout(500)
        check('star a combo', await ev("S.meta.fight.fav.length === 1"))
        await pg.locator('.fc-row .pill-btn').nth(2).click(); await pg.wait_for_timeout(200)
        check('Drill runs one minute of that combo', await ev("FR.T && FR.T.cfg.only === '1-2' && FR.T.cfg.rounds === 1 && FR.T.cfg.round === 60 && fightPool(FR.T.cfg).length === 1"))
        await ev("fightStop(); UI.setView(null)"); await pg.wait_for_timeout(200)
        # Drills: one starts the timer
        await pg.click('#fight-tab-drills'); await pg.wait_for_timeout(200)
        await pg.click('#fd-r-rope summary'); await pg.locator('#fd-r-rope button').click(); await pg.wait_for_timeout(300)
        check('a drill starts the round timer', await ev("!!S.itimer && S.itimer.cfg.work === 180"))
        await ev("S.itimer = null; UI.setView(null)"); await pg.wait_for_timeout(200)
        # Program: workout → coach → rounds fill the exercise
        await pg.click('#fight-tab-programs'); await pg.wait_for_timeout(200)
        check('Programs lists six plus Fight Rounds', await pg.locator('#fight-programs .r-card').count() == 7)
        await pg.click('#fprog-bi-fight-box'); await pg.wait_for_timeout(400)
        info = await pg.locator('#fight-info').inner_text()
        check('program page: strengths, results, watch-outs, coach note', all(x in info for x in ['Strengths', 'Likely results', 'Watch out for', 'qualified coach']))
        await pg.locator('.pill-btn', has_text='Start').first.click(); await pg.wait_for_timeout(400)
        check('workout has a Start the coach button', await pg.locator('#wo-fight').count() == 1 and 'Boxing 3 × 2:00' in await pg.locator('#wo-fight').inner_text())
        yb = await ev("document.getElementById('wo-fight').getBoundingClientRect().top < document.querySelector('.slot').getBoundingClientRect().top")
        check('the coach button is at the top of the workout', yb)
        heads = await ev("[...document.querySelectorAll('.slot')].map(x => [x.querySelector('h3').textContent, x.querySelector('.meas-row.th') ? x.querySelector('.meas-row.th').innerText : ''])")
        sb = [h for n, h in heads if n.startswith('Shadowboxing')][0]
        check('round exercises have no added-weight column', '+' not in sb and 'TIME' in sb.upper(), sb)
        await pg.click('#wo-fight'); await ev("FR.T.startedAt -= 999000"); await pg.wait_for_timeout(500)
        await pg.click('#fight-fill'); await pg.wait_for_timeout(400)
        check('rounds fill the Shadowboxing Rounds sets', await ev("S.active.items.find(i => exName(i.ex) === 'Shadowboxing Rounds').sets.filter(x => +x.t === 120).length === 3"))
        await ev("fightStop(); commit(st => { st.active = null; }, 'active'); UI.setView(null)")
        # Alongside a program, through together.js
        check('a fight day added to a workout brings the coach', await ev("(() => { startWorkout(null, null); const r = getRoutine('bi-fight-thai'); addDayToWorkout(r, r.days[0]); return !!S.active.fight && S.active.fight.style === 'thai'; })()"))
        await ev("commit(st => { st.active = null; }, 'active')")
        await ev("setAddon('bi-fight-thai', true); TRAIN.mode = 'train'; UI.setTab('train'); UI.setView(null)"); await pg.wait_for_timeout(400)
        check('alongside, a fight program is labelled Fight training', (await pg.locator('#also-bi-fight-thai .eyebrow').inner_text()).strip().lower() == 'fight training')
        await ev("setAddon('bi-fight-thai', false)")
        check('an app update never reloads in the middle of rounds', 'FR.T && !FR.T.done' in open('dist/index.html', encoding='utf8').read())
        # Activities and backup
        check('Boxing, Kickboxing / Muay Thai and MMA can be logged', await ev("['boxing', 'kickbox', 'mma', 'bjj'].every(k => ACTS.some(a => a[0] === k))"))
        bk = json.loads(await ev("JSON.stringify(S.meta)"))
        check('fight settings are in meta, so backups carry them', bk.get('fight', {}).get('fav') == ['box:1'])
        check('tour has a Fight step', await ev("TOUR.some(t => t[1] === 'fight' && /combos/.test(t[4]))"))
        await ev("lsSet('rtView', 'type'); lsSet('rtKind', 'plans')"); await pg.reload(); await pg.wait_for_timeout(1200)
        await pg.locator('.tabs button', has_text='Routines').click(); await pg.wait_for_timeout(300)
        check('By type has a Fight training section', 'FIGHT TRAINING' in (await pg.locator('main').inner_text()).upper())
        check('no page errors', not errs, errs[:3]); await b.close()
try: asyncio.run(main())
finally: srv.terminate()
print(f'{sum(results)}/{len(results)} passed'); sys.exit(0 if all(results) else 1)
